            ROUTER_ADDRESS,
            abi.encodeWithSignature("WETH()"),
            abi.encode(mockWETH)
        );

        // Mock factory pair creation
        vm.mockCall(
            mockFactory,
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(mockPair)
        );

        // Deploy contract as owner
        vm.startPrank(owner);
        token = new Play2Burn();
        vm.stopPrank();
    }

    function test_HighFeeSettings() public {
        console2.log("--- BEFORE-Trigger Fees ---");
        // Record initial buy fees
        Play2Burn.Fees memory buyBefore = token.buyFee();
        console2.log("BuyFee initial: liquidity=%d, marketing=%d, reward=%d, tax=%d",
            buyBefore.liquidityFee,
            buyBefore.marketingFee,
            buyBefore.rewardFee,
            buyBefore.taxFee
        );

        // Record initial sell fees
        Play2Burn.Fees memory sellBefore = token.sellFee();
        console2.log("SellFee initial: liquidity=%d, marketing=%d, reward=%d, tax=%d",
            sellBefore.liquidityFee,
            sellBefore.marketingFee,
            sellBefore.rewardFee,
            sellBefore.taxFee
        );

        console2.log("--- Trigger High Fees ---");
        // Owner sets fees to maximum (25 each, 100% total)
        vm.prank(owner);
        token.setBuyFee(25, 25, 25, 25); // 100% total fee

        vm.prank(owner);
        token.setSellFee(25, 25, 25, 25); // 100% total fee

        console2.log("--- AFTER-Trigger Fees ---");
        // Record post-trigger buy fees
        Play2Burn.Fees memory buyAfter = token.buyFee();
        console2.log("BuyFee after: liquidity=%d, marketing=%d, reward=%d, tax=%d",
            buyAfter.liquidityFee,
            buyAfter.marketingFee,
            buyAfter.rewardFee,
            buyAfter.taxFee
        );

        // Record post-trigger sell fees
        Play2Burn.Fees memory sellAfter = token.sellFee();
        console2.log("SellFee after: liquidity=%d, marketing=%d, reward=%d, tax=%d",
            sellAfter.liquidityFee,
            sellAfter.marketingFee,
            sellAfter.rewardFee,
            sellAfter.taxFee
        );

        // Validate all fee components were set to 25 (100% total)
        bool buyFeeExploited = (buyAfter.liquidityFee == 25) &&
                               (buyAfter.marketingFee == 25) &&
                               (buyAfter.rewardFee == 25) &&
                               (buyAfter.taxFee == 25);

        bool sellFeeExploited = (sellAfter.liquidityFee == 25) &&
                                (sellAfter.marketingFee == 25) &&
                                (sellAfter.rewardFee == 25) &&
                                (sellAfter.taxFee == 25);

        // Print vulnerability verdict
        if (buyFeeExploited && sellFeeExploited) {
            console2.log("Vulnerability Exists: Owner can set fees to 100% total, enabling total value extraction");
        } else {
            console2.log("Vulnerability not Exist: Fee limits appear to be working");
        }
    }
}
```

The key modifications are:
1. Added `console2.sol` import for structured logging
2. Added pre-trigger fee component snapshots for both buy/sell fees
3. Added post-trigger fee component snapshots
4. Implemented rigorous fee component comparison logic
5. Added a final vulnerability verdict based on state changes

The differential validation checks:
- Before and after each fee component value
- Whether all components successfully changed to the excessive 25% setting
- Whether the total fee reaches the dangerous 100% threshold

The final verdict outputs `Vulnerability Exists` only if both buy/sell fees were successfully set to four 25% components (100% total), confirming the centralization risk.

